from modele import C,E

C('Passer par la dizaine','Calcul','P3',
 'Je décompose un petit nombre pour ajouter.','Une boîte de dix, des barres et des unités.',
 'Pose 8 jetons. Ajoute 5 jetons en remplissant d’abord la boîte de dix.',
 ['Je cherche ce qui manque pour atteindre la dizaine suivante.', 'Je décompose le nombre ajouté pour atteindre cette dizaine.', 'Pour ajouter 9, je peux ajouter 10 puis enlever 1.'],
 '28 + 5 : j’ajoute 2, puis 3. 28 + 2 = 30 ; 30 + 3 = 33.',('jumps',[28,30,33]),
 'Calcule 19 + 4 en passant par 20.', '19 + 1 = 20 ; 20 + 3 = 23. Donc 19 + 4 = 23.',[
 E('Observe les sauts. Explique comment calculer 36 + 7 en passant par 40.','36 + 4 = 40 ; 40 + 3 = 43. Donc 36 + 7 = 43.',('jumps',[36,40,43]),'36+7==43'),
 E('Combien manque-t-il pour atteindre la dizaine suivante : 47 ; 62 ; 85 ?','3 pour 50 ; 8 pour 70 ; 5 pour 90.'),
 E('Calcule en passant par 10 : 8 + 6 ; 7 + 5.','8 + 2 = 10, puis + 4 : 14. 7 + 3 = 10, puis + 2 : 12.',None,'8+6==14 and 7+5==12'),
 E('Calcule : 48 + 5 ; 67 + 6 ; 89 + 4.','53 ; 73 ; 93.',None,'48+5==53 and 67+6==73 and 89+4==93'),
 E('Calcule avec + 10 puis - 1 : 26 + 9 ; 54 + 9.','26 + 10 = 36, puis 35. 54 + 10 = 64, puis 63.',None,'26+9==35 and 54+9==63'),
 E('Calcule : 30 + 9 ; 61 + 9. Choisis une méthode simple.','39 ; 70. Pour 30 + 9, il suffit d’ajouter 9 unités.',None,'30+9==39 and 61+9==70'),
 E('Jade a 27 cartes. Elle en reçoit 6. Combien de cartes a-t-elle ?','27 + 3 = 30 ; 30 + 3 = 33. Jade a 33 cartes.',None,'27+6==33'),
 E('Une boîte contient 72 perles. On en ajoute 9. Combien y en a-t-il ?','72 + 10 = 82 ; 82 - 1 = 81. Il y a 81 perles.',None,'72+9==81'),
 E('Nino écrit : « 38 + 5 = 40 + 3 = 43 ». Est-ce vrai ?','Oui : 38 + 5 et 40 + 3 valent tous deux 43. 5 est décomposé en 2 + 3.')],
 'Faire déplacer les unités qui remplissent d’abord la dizaine.', 'Éviter la fausse chaîne 38 + 2 = 40 + 3 = 43 : 40 et 43 ne sont pas égaux.')

C('Additionner de tête','Calcul','P3',
 'Je décompose des nombres pour calculer leur somme.','Des barres de dix et des cubes.',
 'Construis 24 et 35. Réunis les dizaines, puis les unités. Essaie ensuite 27 et 36.',
 ['Je sépare les dizaines et les unités.', 'J’ajoute les dizaines ensemble, puis les unités ensemble.', 'Si je réunis 10 unités, je les échange contre une dizaine.'],
 '27 + 36 : 20 + 30 = 50 ; 7 + 6 = 13 ; 50 + 13 = 63.',('sumtree',[27,36]),
 'Calcule 32 + 24 en décomposant.', '30 + 20 = 50 ; 2 + 4 = 6 ; 50 + 6 = 56.',[
 E('Observe ce calcul. Explique comment les dizaines et les unités sont regroupées.','20 + 10 = 30 ; 3 + 5 = 8 ; 30 + 8 = 38.',('sumtree',[23,15]),'23+15==38'),
 E('Calcule : 41 + 26 ; 35 + 22.','67 ; 57.',None,'41+26==67 and 35+22==57'),
 E('Décompose et calcule : 28 + 14.','20 + 10 = 30 ; 8 + 4 = 12 ; 30 + 12 = 42.',None,'28+14==42'),
 E('Calcule : 46 + 27 ; 58 + 16.','73 ; 74.',None,'46+27==73 and 58+16==74'),
 E('Calcule : 24 + 36 ; 39 + 41.','60 ; 80.',None,'24+36==60 and 39+41==80'),
 E('Ajoute trois nombres : 12 + 23 + 15.','12 + 23 = 35 ; 35 + 15 = 50. On peut aussi commencer par 23 + 15 = 38, puis ajouter 12.',None,'12+23+15==50'),
 E('La classe a 34 crayons bleus et 28 rouges. Combien de crayons a-t-elle ?','30 + 20 = 50 ; 4 + 8 = 12 ; 50 + 12 = 62 crayons.',None,'34+28==62'),
 E('Un bac contient 45 cubes. Un autre en contient 37. Combien en contiennent-ils ensemble ?','45 + 37 = 82. Les deux bacs contiennent 82 cubes.',None,'45+37==82'),
 E('Maya trouve 58 + 24 = 712. Explique ce qui ne va pas.','5 dizaines et 2 dizaines font 7 dizaines, soit 70. 8 + 4 = 12. Il faut ajouter 70 et 12 : 82, pas accoler 7 et 12.',None,'58+24==82')],
 'Noter les résultats intermédiaires sur une ardoise, puis alléger cette trace.', 'La somme reste dans le champ 0 à 100 ; ne pas faire juxtaposer les résultats.')

C('Soustraire avec les dizaines','Calcul','P3',
 'Je peux échanger une dizaine contre dix unités.','Des barres de dix qui se démontent.',
 'Construis 40. Pour enlever 6 unités, démonte une barre. Tu as 3 dizaines et 10 unités.',
 ['Une dizaine peut être échangée contre 10 unités.', 'Je retire les unités demandées, puis je compte ce qui reste.', 'Je contrôle mon résultat par une addition.'],
 '40 - 6 : 40 = 30 + 10. J’enlève 6 aux 10 unités. 30 + 4 = 34.',('exchange',[40,6]),
 'Construis 30, puis enlève 4 unités.', '30 = 20 + 10 ; 10 - 4 = 6. Il reste 26.',[
 E('Enlève 7 unités à 50. Aide-toi de l’échange.','50 = 40 + 10 ; 10 - 7 = 3. Donc 50 - 7 = 43.',('exchange',[50,7]),'50-7==43'),
 E('Calcule : 20 - 3 ; 60 - 8 ; 90 - 5.','17 ; 52 ; 85.',None,'20-3==17 and 60-8==52 and 90-5==85'),
 E('Vérifie 70 - 4 = 66 avec une addition.','66 + 4 = 70. Le résultat est correct.'),
 E('Construis 32. Enlève 5 unités. Échange une dizaine si nécessaire.','32 = 20 + 12 ; 12 - 5 = 7. Donc 32 - 5 = 27.',None,'32-5==27'),
 E('Construis 43 et enlève 18 avec le matériel.','43 = 30 + 13. On retire 1 dizaine et 8 unités. Il reste 2 dizaines et 5 unités : 25.',None,'43-18==25'),
 E('Avec le matériel, calcule 51 - 24.','51 = 40 + 11. On retire 20 et 4. Il reste 27.',None,'51-24==27'),
 E('Il y a 30 perles. On en utilise 7. Combien reste-t-il de perles ?','30 - 7 = 23. Il reste 23 perles.',None,'30-7==23'),
 E('Le jardin a 42 fleurs. On cueille 16 fleurs. Combien en reste-t-il ?','42 = 30 + 12. Après retrait de 10 et de 6, il reste 26 fleurs.',None,'42-16==26'),
 E('En échangeant une barre contre 10 cubes, as-tu changé la quantité totale ? Explique.','Non. Une barre de dix vaut exactement dix cubes. Seule l’organisation change.')],
 'Autoriser le matériel pour les retraits avec échange : le sens précède l’automatisation.', 'Cette activité ne demande pas la technique de soustraction posée en colonnes.')

C('Chercher une partie ou le départ','Problèmes','P2 et P3',
 'Je cherche ce qui manque dans une histoire.','Des jetons et une feuille.',
 'Cache une partie de 12 jetons sous une boîte. Laisse 5 jetons visibles. Cherche combien sont cachés.',
 ['Je repère le tout et les parties.', 'Pour chercher une partie, je peux soustraire ou compléter.', 'Pour chercher le départ, je reconstruis l’histoire à l’envers.'],
 'Il y a 18 perles en tout, dont 7 rouges. Les autres sont bleues. 18 - 7 = 11.',('bar',[18,7,'?']),
 'Il y a 15 cartes, dont 6 sont visibles. Combien sont cachées ?', '15 - 6 = 9. Il y a 9 cartes cachées.',[
 E('Il y a 20 billes en tout, dont 8 vertes. Les autres sont jaunes. Combien sont jaunes ?','20 - 8 = 12. Il y a 12 billes jaunes.',('bar',[20,8,'?']),'20-8==12'),
 E('Complète : 7 + … = 13 ; 24 + … = 30.','6 ; 6.',None,'7+6==13 and 24+6==30'),
 E('16 oiseaux étaient dans un arbre. Il en reste 9. Combien se sont envolés ?','16 - 9 = 7. 7 oiseaux se sont envolés.',None,'16-9==7'),
 E('J’avais des images. J’en donne 4 et il m’en reste 12. Combien en avais-je ?','12 + 4 = 16. J’avais 16 images.',None,'12+4==16'),
 E('J’avais des cubes. J’en reçois 6 et j’en ai maintenant 21. Combien en avais-je ?','21 - 6 = 15. J’avais 15 cubes.',None,'21-6==15'),
 E('Un album a 50 places. 32 sont occupées. Combien de places sont libres ?','50 - 32 = 18. Il reste 18 places libres.',None,'50-32==18'),
 E('Lina a 27 crayons en tout : 10 bleus, 8 rouges et les autres verts. Combien sont verts ?','10 + 8 = 18 ; 27 - 18 = 9. Il y a 9 crayons verts.',None,'27-10-8==9'),
 E('Une boîte contient 64 perles. 29 sont prises. Combien restent dans la boîte ? Utilise des dizaines.','64 - 29 = 35. On peut échanger une dizaine pour retirer les unités.',None,'64-29==35'),
 E('Un enfant dit : « J’ai donné 5 cartes et il m’en reste 14 ; j’en avais donc 9. » Vérifie.','S’il en avait 9, il en resterait 4. Il en avait 14 + 5 = 19.',None,'14+5==19')],
 'Dessiner une barre pour le tout et deux parties, puis nommer l’inconnue.', 'Le mot « donne » n’impose pas une soustraction : on peut chercher la quantité initiale.')

C('Des groupes de même taille','Problèmes','P3',
 'Je réunis plusieurs groupes identiques.','Des jetons et de petites boîtes.',
 'Pose 3 boîtes. Mets 4 jetons dans chacune. Compte tous les jetons et raconte « trois fois quatre ».',
 ['Chaque groupe doit contenir le même nombre d’objets.', 'Je peux additionner plusieurs fois la même quantité.', 'Je dis « trois fois quatre » pour trois groupes de quatre.'],
 '3 groupes de 4 font 4 + 4 + 4 = 12 objets.',('groups',[3,4]),
 'Fais 2 groupes de 5. Combien d’objets en tout ?', '5 + 5 = 10. Il y a 10 objets.',[
 E('Combien de groupes vois-tu ? Combien de jetons en tout ?','4 groupes de 3. 3 + 3 + 3 + 3 = 12 jetons.',('groups',[4,3]),'4*3==12'),
 E('Dessine 3 groupes de 2 ronds. Écris l’addition.','2 + 2 + 2 = 6.',None,'3*2==6'),
 E('Calcule : 5 + 5 + 5 ; 2 + 2 + 2 + 2.','15 ; 8.',None,'5+5+5==15 and 2+2+2+2==8'),
 E('Il y a 4 paquets de 5 cartes. Combien de cartes en tout ?','5 + 5 + 5 + 5 = 20 cartes.',None,'4*5==20'),
 E('Il y a 3 paniers de 6 balles. Combien de balles en tout ?','6 + 6 + 6 = 18 balles.',None,'3*6==18'),
 E('Dessine 2 rangées de 7 points. Combien de points as-tu dessinés ?','7 + 7 = 14 points.',None,'2*7==14'),
 E('Chaque voiture transporte 4 enfants. Il y a 5 voitures remplies. Combien d’enfants sont transportés ?','4 + 4 + 4 + 4 + 4 = 20 enfants.',None,'5*4==20'),
 E('Une fleur a 5 pétales. Tu dessines 6 fleurs identiques. Combien de pétales dessines-tu ?','5 + 5 + 5 + 5 + 5 + 5 = 30 pétales.',None,'6*5==30'),
 E('Les boîtes contiennent 3, 3 et 4 jetons. Peut-on dire « trois groupes de trois » ?','Non. La troisième boîte contient 4 jetons. 3 + 3 + 4 = 10 jetons.')],
 'Entourer chaque groupe et vérifier qu’ils ont tous le même effectif.', 'Le sens de « fois » est travaillé sans exiger les tables ni le symbole de multiplication.')

C('Partager équitablement','Problèmes','P3',
 'Je distribue en parts égales ou je forme des paquets.','24 jetons et quatre assiettes.',
 'Partage 12 jetons entre 3 assiettes, un par un. Ensuite forme des paquets de 3 avec 12 jetons.',
 ['Partager équitablement, c’est donner autant à chacun.', 'Je peux chercher combien il y a dans chaque part.', 'Je peux aussi chercher combien de paquets sont possibles.'],
 '12 jetons pour 3 enfants : chacun reçoit 4 jetons. 4 + 4 + 4 = 12.',('groups',[3,4]),
 'Avec 10 jetons, fais des paquets de 2.', 'On obtient 5 paquets de 2 jetons.',[
 E('Partage 12 jetons entre 2 enfants. Combien chacun reçoit-il ?','6 jetons chacun. 6 + 6 = 12.',('dots',12),'12//2==6'),
 E('Avec 15 jetons, fais des paquets de 5. Combien de paquets ?','3 paquets : 5 + 5 + 5 = 15.',None,'15//5==3'),
 E('Partage 18 cartes entre 3 enfants. Combien de cartes chacun reçoit-il ?','6 cartes chacun : 6 + 6 + 6 = 18.',None,'18//3==6'),
 E('Avec 20 cubes, fais des tours de 4 cubes. Combien de tours ?','5 tours de 4 cubes.',None,'20//4==5'),
 E('Partage 24 perles entre 4 enfants. Combien chacun reçoit-il ?','6 perles chacun.',None,'24//4==6'),
 E('Une bande est pliée en deux parts égales. Comment appelle-t-on chaque part ?','Une moitié ou une demi-bande.',('fraction',[2,1])),
 E('Une bande est partagée en 4 parts égales. Colorie une seule part. Comment s’appelle cette part ?','Un quart de la bande.',('fraction',[4,0])),
 E('24 enfants forment des équipes de 6. Combien d’équipes peut-on faire ?','4 équipes : 6 + 6 + 6 + 6 = 24.',None,'24//6==4'),
 E('Lina partage 10 cartes en donnant 6 à l’un et 4 à l’autre. Le partage est-il équitable ? Corrige.','Non. Pour deux parts égales, chacun reçoit 5 cartes.')],
 'Distribuer un objet à chacun à chaque tour ; vérifier par recomposition.', 'Moitié, demi et quart restent du vocabulaire concret, sans écriture fractionnaire exigée.')

C('Résoudre en deux étapes','Problèmes','P4',
 'Je garde une trace de chaque étape d’une histoire.','Des jetons, une feuille et un crayon.',
 'Pose 18 jetons. Enlève-en 5, puis ajoute-en 4. Dessine les deux changements.',
 ['Je raconte ce qui se passe dans l’ordre.', 'Je garde le résultat de la première étape pour la suivante.', 'Je réponds avec une phrase et je vérifie l’histoire.'],
 '18 enfants sont là. 5 partent, puis 4 arrivent. 18 - 5 = 13 ; 13 + 4 = 17.',('story',[18,-5,4]),
 'Il y a 12 cubes. On en ajoute 6, puis on en prend 3.', '12 + 6 = 18 ; 18 - 3 = 15. Il reste 15 cubes.',[
 E('Il y a 20 oiseaux. 6 partent, puis 3 arrivent. Combien sont là à la fin ?','20 - 6 = 14 ; 14 + 3 = 17 oiseaux.',('storyblank',[20,-6,3]),'20-6+3==17'),
 E('J’ai 8 cartes. Je reçois 7 cartes, puis 4 autres. Combien en ai-je ?','8 + 7 = 15 ; 15 + 4 = 19 cartes.',None,'8+7+4==19'),
 E('Il y a 25 perles. On en utilise 8, puis 5. Combien en reste-t-il ?','25 - 8 = 17 ; 17 - 5 = 12 perles.',None,'25-8-5==12'),
 E('Dans une boîte de 24 crayons, 7 sont rouges et 9 sont bleus. Les autres sont verts. Combien sont verts ?','7 + 9 = 16 ; 24 - 16 = 8 crayons verts.',None,'24-7-9==8'),
 E('Un bus contient 23 enfants. 10 descendent et 6 montent. Combien y a-t-il d’enfants ?','23 - 10 = 13 ; 13 + 6 = 19 enfants.',None,'23-10+6==19'),
 E('J’ai 15 €. Je paie 4 €, puis 6 €. Combien me reste-t-il ?','15 - 4 = 11 ; 11 - 6 = 5 €. Il reste 5 €.',None,'15-4-6==5'),
 E('Une étagère porte 9 albums, 8 documentaires et 6 bandes dessinées. Combien de livres ?','9 + 8 = 17 ; 17 + 6 = 23 livres.',None,'9+8+6==23'),
 E('Un jeu a 30 cases. Le pion part de 12, avance de 7, puis recule de 4. Sur quelle case arrive-t-il ?','12 + 7 = 19 ; 19 - 4 = 15. Il arrive sur la case 15.',None,'12+7-4==15'),
 E('J’ai 22 cubes. J’en donne 5 puis j’en reçois 3. Hugo répond 14. Vérifie et corrige.','22 - 5 = 17 ; 17 + 3 = 20. Hugo a enlevé 3 au lieu de les ajouter.',None,'22-5+3==20')],
 'Dessiner une case par état et une flèche par changement.', 'Garder toutes les quantités et tous les résultats intermédiaires dans le champ 0 à 30.')
